"use client";

import { useState } from "react";

export function TagInput({ tags, onChange }: { tags: string[]; onChange: (tags: string[]) => void }) {
  const [value, setValue] = useState("");
  function add() {
    const name = value.trim().replace(/\s+/g, " ");
    if (!name || tags.some((tag) => tag.toLocaleLowerCase() === name.toLocaleLowerCase())) return setValue("");
    if (tags.length < 50) onChange([...tags, name]);
    setValue("");
  }
  return (
    <div className="tag-editor">
      {tags.length > 0 && <ul className="tag-list" aria-label="Selected tags">{tags.map((tag) => (
        <li key={tag} className="tag"><span>{tag}</span><button type="button" onClick={() => onChange(tags.filter((item) => item !== tag))} aria-label={`Remove ${tag} tag`}>×</button></li>
      ))}</ul>}
      <div className="tag-entry">
        <input value={value} maxLength={50} placeholder="Add a tag" aria-label="Tag name" onChange={(event) => setValue(event.target.value)} onKeyDown={(event) => { if (event.key === "Enter" || event.key === ",") { event.preventDefault(); add(); } }} />
        <button className="button secondary small" type="button" onClick={add} disabled={!value.trim()}>Add</button>
      </div>
      <p className="field-hint">Press Enter or comma to add a tag.</p>
    </div>
  );
}

/work/components/types.ts.content:
export type Bookmark = {
  id: string; url: string; title: string; titleOrigin: "fetched" | "fallback" | "user";
  note: string; iconPath?: string | null; tags: string[]; createdAt: string; updatedAt: string;
};

export type Preview = {
  normalizedUrl: string; title: string; titleOrigin: "fetched" | "fallback";
  iconToken?: string | null; warning?: string | null; existingBookmarkId?: string | null;
};

export type ApiError = { error?: { code?: string; message?: string; field?: string; existingId?: string } };

export async function jsonRequest<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, init);
  if (!response.ok) {
    let body: ApiError = {};
    try { body = await response.json() as ApiError; } catch { /* use generic message */ }
    const error = new Error(body.error?.message || "Something went wrong. Please try again.");
    Object.assign(error, { status: response.status, existingId: body.error?.existingId });
    throw error;
  }
  if (response.status === 204) return undefined as T;
  return response.json() as Promise<T>;
}

