.nav-note { color:var(--muted); font-size:.85rem; }
.page-shell { min-height:80vh; }
.hero { padding:4.5rem max(1.5rem,calc((100vw - 1180px)/2)); display:grid; grid-template-columns:minmax(300px,.85fr) minmax(420px,1.15fr); gap:6vw; align-items:center; background:linear-gradient(135deg,#f2efe5,#f8f6f0 60%,#e8eee8); border-bottom:1px solid var(--line); }
.eyebrow { display:block; color:var(--sage); font-size:.73rem; font-weight:800; letter-spacing:.15em; text-transform:uppercase; margin-bottom:.55rem; }
h1,h2 { font-family:Georgia,"Times New Roman",serif; line-height:1.05; margin:0; font-weight:500; }
